CREATE TABLE IF NOT EXISTS cliente(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,telefone TEXT,cpf TEXT,email TEXT UNIQUE NOT NULL,senha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS endereco(id INTEGER PRIMARY KEY AUTOINCREMENT,cliente_id INTEGER NOT NULL REFERENCES cliente(id),rua TEXT,numero INTEGER,bairro TEXT,cep TEXT,complemento TEXT);
CREATE TABLE IF NOT EXISTS categoria(id INTEGER PRIMARY KEY AUTOINCREMENT,tipo TEXT NOT NULL,restricao TEXT DEFAULT 'nenhuma');
CREATE TABLE IF NOT EXISTS produto(id INTEGER PRIMARY KEY AUTOINCREMENT,categoria_id INTEGER REFERENCES categoria(id),nome TEXT NOT NULL,preco REAL NOT NULL,ingredientes TEXT,estoque INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS motoboy(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT,placa TEXT,telefone TEXT);
CREATE TABLE IF NOT EXISTS confeiteiro(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT,turno TEXT);
CREATE TABLE IF NOT EXISTS pedido(id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT UNIQUE,cliente_id INTEGER NOT NULL REFERENCES cliente(id),motoboy_id INTEGER REFERENCES motoboy(id),status TEXT DEFAULT 'Aprovado',forma_pgto TEXT,valor_total REAL,frete REAL,data_hora TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS item_pedido(id INTEGER PRIMARY KEY AUTOINCREMENT,pedido_id INTEGER NOT NULL REFERENCES pedido(id),produto_id INTEGER REFERENCES produto(id),confeiteiro_id INTEGER REFERENCES confeiteiro(id),quantidade INTEGER,massa TEXT,recheio TEXT,cobertura TEXT,subtotal REAL);
